fn solve(s: Vec<char>) -> Vec<char> {
    // We know `s.len() == 19`. We'll build a new Vec<char> of length 20.
    let mut result = Vec::with_capacity(s.len() + 1);

    // For each character in the input:
    // - if it's a comma, push a space
    // - otherwise, push it unchanged
    for c in s {
        if c == ',' {
            result.push(' ');
        } else {
            result.push(c);
        }
    }

    // Finally append the newline character
    result.push('\n');
    result
}

