    #[test]
    fn test_replace_commas_and_append_newline() {
        let input: Vec<char> = "abcde,fghijkl,mnopq".chars().collect(); 
        // indices 5 and 13 are commas by construction
        let output = solve(input);

        // Check length
        assert_eq!(output.len(), 20);

        // Check the newline at the end
        assert_eq!(output[19], '\n');

        // Check each character up to index 18
        let expected_prefix: Vec<char> = "abcde fghijkl mnopq".chars().collect();
        for i in 0..19 {
            assert_eq!(output[i], expected_prefix[i]);
        }
    }
